            mtime_nanos: metadata.modified().map_or(0, crate::find::nanos_of),
            mtime_seconds: crate::wire_metadata::mtime_seconds(metadata).unwrap_or(0),
            allocated: if metadata.is_dir() { 0 } else { metadata.len() },
