/// lives.
#[cfg(all(test, unix))]
pub(crate) fn before_each_entering(hook: impl FnMut(&Path) + 'static) -> impl Drop {
    struct Cleared;
    impl Drop for Cleared {
        fn drop(&mut self) {
            BEFORE_ENTERING.with(|hook| hook.borrow_mut().take());
        }
    }
    BEFORE_ENTERING.with(|slot| *slot.borrow_mut() = Some(Box::new(hook)));
